//! Platform-agnostic error type and user-facing rendering.
//! (Generated by v0.6.0 Step 3 Phase 1)

use thiserror::Error;

use crate::github::GithubError;
use crate::platform::remote::PlatformKind;

/// Errors produced by platform clients.
///
/// Network/HTTP failures are normalized into the [`Http`], [`Network`], and
/// [`Other`] variants so the UI can render a stable message through
/// [`render_platform_error`] regardless of the underlying adapter (octocrab,
/// reqwest, …).
#[derive(Debug, Error, PartialEq, Eq)]
pub enum PlatformError {
    /// No usable token could be resolved for the platform.
    #[error("{0}")]
    Token(String),

    /// The repository's remote URL does not point at a supported platform.
    #[error("{0}")]
    NotPlatform(String),

    /// The platform API answered with an HTTP error status.
    #[error("{message}")]
    Http {
        /// HTTP status code (e.g. 401, 403, 404, 429).
        status: u16,
        /// Message reported by the API, when available.
        message: String,
        /// Whether the API signalled rate limiting.
        rate_limited: bool,
        /// Platform label (`"GitHub"`, `"GitLab"`, `"Gitea"`, … — the values of
        /// [`PlatformKind::as_str`]).
        platform: &'static str,
    },

    /// The request failed before the API responded (DNS, TLS, connect, …).
    #[error("{0}")]
    Network(String),

    /// Any other platform error.
    #[error("{message}")]
    Other {
        platform: &'static str,
        message: String,
    },
}

/// Map [`GithubError`] → [`PlatformError`] (platform label = `"GitHub"`).
impl From<GithubError> for PlatformError {
    fn from(e: GithubError) -> Self {
        let platform = PlatformKind::GitHub.as_str();
        match e {
            GithubError::Token(m) => PlatformError::Token(m),
            GithubError::NotGitHub(m) => PlatformError::NotPlatform(m),
            GithubError::Http {
                status,
                message,
                rate_limited,
            } => PlatformError::Http {
                status,
                message,
                rate_limited,
                platform,
            },
            GithubError::Network(m) => PlatformError::Network(m),
            GithubError::Other(m) => PlatformError::Other {
                platform,
                message: m,
            },
        }
    }
}

/// Actionable 401 message for `platform`.
///
/// The credential names come from [`PlatformKind::token_var`] /
/// [`PlatformKind::cli_hint`] — the single source every platform hint shares —
/// resolved from the platform label ([`PlatformKind::as_str`]). An empty
/// `cli_hint` means the platform has no token CLI, so only the env var is
/// named; an unknown label and self-hosted keep the neutral wording (no host
/// owns a token var there) and never panic.
fn token_hint(platform: &str) -> String {
    use crate::platform::PlatformKind;
    let Some(kind) = kind_from_label(platform) else {
        return format!("{platform} 认证失败，请检查令牌");
    };
    if kind == PlatformKind::SelfHosted {
        return format!("{platform} 认证失败，请检查令牌");
    }
    let cli = kind.cli_hint();
    if cli.is_empty() {
        format!("{platform} 认证失败，请检查 {}", kind.token_var())
    } else {
        format!(
            "{platform} 认证失败，请检查 {} 或 {cli} auth token",
            kind.token_var()
        )
    }
}

/// Resolve a platform label back to its [`PlatformKind`].
///
/// `PlatformError::Http`/`Other` carry a `&'static str` label, so the reverse
/// lookup keeps the token hint in step with [`PlatformKind`] instead of
/// re-deriving the platform from a duplicated literal.
fn kind_from_label(label: &str) -> Option<PlatformKind> {
    [
        PlatformKind::GitHub,
        PlatformKind::GitLab,
        PlatformKind::Gitea,
        PlatformKind::SelfHosted,
    ]
    .into_iter()
    .find(|kind| kind.as_str() == label)
}

/// Render a platform error as a short, user-facing line.
///
/// Routes the status-aware mapping through the stored platform label so
/// GitHub/GitLab/Gitea messages stay consistent and actionable.
pub fn render_platform_error(e: &PlatformError) -> String {
    match e {
        PlatformError::Token(m) | PlatformError::NotPlatform(m) => m.clone(),
        PlatformError::Network(_) => "网络错误，请检查网络连接".to_string(),
        PlatformError::Http {
            status,
            message,
            rate_limited,
            platform,
        } => {
            if *rate_limited || *status == 429 {
                return format!("{platform} 速率限制，请稍后重试");
            }
            match *status {
                401 => token_hint(platform),
                403 => "无权限访问该资源".to_string(),
                404 => format!("{platform} 仓库/资源不存在或无权限"),
                500..=599 => format!("{platform} 服务端错误，请稍后重试"),
                _ => {
                    if message.is_empty() {
                        format!("{platform} HTTP {status}")
                    } else {
                        message.clone()
                    }
                }
            }
        }
        PlatformError::Other { platform, message } => {
            format!("{platform} 错误: {message}")
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn http(status: u16, platform: &'static str) -> PlatformError {
        PlatformError::Http {
            status,
            message: String::new(),
            rate_limited: false,
            platform,
        }
    }

    #[test]
    fn from_github_error_maps_https_with_platform_label() {
        let e: PlatformError = GithubError::Http {
            status: 404,
            message: "nope".into(),
            rate_limited: false,
        }
        .into();
        assert!(matches!(
            e,
            PlatformError::Http {
                status: 404,
                platform: "GitHub",
                ..
            }
        ));
    }

    #[test]
    fn from_github_error_network_passthrough() {
        let e: PlatformError = GithubError::Network("dns fail".into()).into();
        assert!(matches!(e, PlatformError::Network(_)));
    }

    #[test]
    fn from_github_error_other_carries_label() {
        let e: PlatformError = GithubError::Other("boom".into()).into();
        assert!(matches!(
            e,
            PlatformError::Other {
                platform: "GitHub",
                message
            } if message == "boom"
        ));
    }

    #[test]
    fn render_401_gives_actionable_token_hint_per_platform() {
        assert_eq!(
            render_platform_error(&http(401, "GitHub")),
            "GitHub 认证失败，请检查 GITHUB_TOKEN 或 gh auth token"
        );
        assert_eq!(
            render_platform_error(&http(401, "GitLab")),
            "GitLab 认证失败，请检查 GITLAB_TOKEN 或 glab auth token"
        );
        assert_eq!(
            render_platform_error(&http(401, "Gitea")),
            "Gitea 认证失败，请检查 GITEA_TOKEN"
        );
        // Unknown label (defensive): generic wording, no panic.
        assert_eq!(
            render_platform_error(&http(401, "SelfHosted")),
            "SelfHosted 认证失败，请检查令牌"
        );
    }

    #[test]
    fn render_404_names_the_platform() {
        assert_eq!(
            render_platform_error(&http(404, "GitLab")),
            "GitLab 仓库/资源不存在或无权限"
        );
        assert_eq!(
            render_platform_error(&http(404, "Gitea")),
            "Gitea 仓库/资源不存在或无权限"
        );
        assert_eq!(
            render_platform_error(&http(404, "GitHub")),
            "GitHub 仓库/资源不存在或无权限"
        );
    }

    #[test]
    fn render_rate_limited() {
        let e: PlatformError = GithubError::Http {
            status: 429,
            message: String::new(),
            rate_limited: false,
        }
        .into();
        assert_eq!(render_platform_error(&e), "GitHub 速率限制，请稍后重试");
    }

    #[test]
    fn render_network_is_generic() {
        let e: PlatformError = GithubError::Network("dns fail".into()).into();
        assert_eq!(render_platform_error(&e), "网络错误，请检查网络连接");
    }

    #[test]
    fn render_unknown_status_falls_back_to_message() {
        assert_eq!(render_platform_error(&http(418, "Gitea")), "Gitea HTTP 418");
        let with_message = PlatformError::Http {
            status: 418,
            message: "teapot".into(),
            rate_limited: false,
            platform: "Gitea",
        };
        assert_eq!(render_platform_error(&with_message), "teapot");
        let other = PlatformError::Other {
            platform: "GitLab",
            message: "boom".into(),
        };
        assert_eq!(render_platform_error(&other), "GitLab 错误: boom");
    }
}
